_cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// ------------------------------------------------------------------
// CUDA kernel: each thread computes one output element.
// ------------------------------------------------------------------
__global__ void conv3d_fp16_kernel(const half* __restrict__ input,
                                   const half* __restrict__ weight,
                                   half* __restrict__ output,
                                   int N, int Cin, int Cout,
                                   int D, int W, int H,
                                   int K,
                                   int D_out, int W_out, int H_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cout * D_out * W_out * H_out;
    if (idx >= total) return;

    // Decode linear index into (n, cout, d_out, w_out, h_out)
    int n = idx / (Cout * D_out * W_out * H_out);
    int rem = idx % (Cout * D_out * W_out * H_out);
    int cout_idx = rem / (D_out * W_out * H_out);
    rem = rem % (D_out * W_out * H_out);
    int d_out = rem / (W_out * H_out);
    rem = rem % (W_out * H_out);
    int w_out = rem / H_out;
    int h_out = rem % H_out;

    float sum = 0.0f;

    // Naive convolution over input channels and kernel volume
    for (int c = 0; c < Cin; ++c) {
        for (int kd = 0; kd < K; ++kd) {
            int d_in = d_out + kd;
            for (int kw = 0; kw < K; ++kw) {
                int w_in = w_out + kw;
                for (int kh = 0; kh < K; ++kh) {
                    int h_in = h_out + kh;

                    int input_idx = n * (Cin * D * W * H)
                                  + c * (D * W * H)
                                  + d_in * (W * H)
                                  + w_in * H
                                  + h_in;

                    int weight_idx = cout_idx * (Cin * K * K * K)
                                   + c * (K * K * K)
                                   + kd * (K * K)
                                   + kw * K
                                   + kh;

                    sum += __half2float(input[input_idx]) *
                           __half2float(weight[weight_idx]);
                }
            }
        }
    }

    output[idx] = __float2half(sum);
}

// ------------------------------------------------------------------
// Python‑exposed wrapper
// ------------------------------------------------------------------
torch::Tensor conv3d_fp16(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be half precision");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be half precision");

    int N   = input.size(0);
    int Cin = input.size(1);
    int D   = input.size(2);
    int W   = input.size(3);
    int H   = input.size(4);

    int Cout = weight.size(0);
    int K    = weight.size(2);          // kernel size (cubic)

    TORCH_CHECK(weight.size(1) == Cin, "weight in_channels mismatch");
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K,
                "kernel must be cubic");

    int D_out = D - K + 1;
    int W_out = W - K + 1;
    int H_out = H - K + 1;

    auto opts = torch::TensorOptions()
                    .dtype(torch::kHalf)
                    .device(input.device());

    torch::Tensor output = torch::empty({N, Cout, D_out, W_out, H_out}, opts);

    const int threads = 256;
    const int total   = N * Cout * D_out * W_out * H_out;
    const int blocks  = (total + threads - 1) / threads;

    conv3d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<const half*>(weight.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        N, Cin, Cout,
        D, W, H,
        K,
        D_out, W_out, H_out
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in conv3d_fp16_kernel: %s\\n", cudaGetErrorString(err));
    }

    return output;
}

// ------------------------------------------------------------------
// PyBind registration
// ------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_fp16", &conv3d_fp16, "3D convolution (FP16) CUDA implementation");
}
'''

# Compile the extension inline
_my_ops = load_inline(name='my_ops',
                      cpp_sources=_cpp_src,
                      cuda_sources=_cuda_src,
                      functions=['conv3d_fp16'],
                      verbose=False)

# ----------------------------------------------------------------------
# ModelNew – drop‑in replacement for the reference Model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    3D convolution using the custom CUDA kernel.
    Supports only the default arguments: stride=1, padding=0,
    dilation=1, groups=1, bias=False.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert stride == 1 and padding == 0 and dilation == 1 and groups == 1 and not bias, \
            "ModelNew only implements the default convolution parameters used in the test."
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # Weight tensor (Cout, Cin, K, K, K) in half precision on CUDA
        self.weight = nn.Parameter(
            torch.randn(out_channels,
                        in_channels,
                        kernel_size,
                        kernel_size,
                        kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is half‑precision CUDA tensor
        x = x.to(dtype=torch.float16, device='cuda')
        return _my_ops.conv3d_fp16(x, self.weight)

# ----------------------------------------------------------------------
# Example usage (mirrors the reference test)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 16
    in_channels = 3
    out_channels = 64
    kernel_size = 3
    depth = 64
    width = 64
    height = 64

    model = ModelNew(in_channels, out_channels, kernel_size)
    x = torch.rand(batch_size, in_channels, depth, width, height,
                   dtype=torch.float16, device='cuda')
    y = model(x)
    print(f"Output shape: {y.shape}")
